#include "stdafx.h"#include "H_Class.h"static SBlockCreate TRIG( "TRIG", SH_TRIG::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_TRIG,W_TRIG,4)void SH_TRIG::InitParm(){#include "Blocks/TRIG.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/TRIG_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class TRIG_IMPL : public W_TRIG{public:  void StepT( SStepCalcParams &dt, bool prevIn );};void SH_TRIG::StepT( SStepCalcParams &dt ){  TRIG_IMPL *impl = reinterpret_cast<TRIG_IMPL*>(W);  bool prevIn = impl->IN;  InputConnectionsTransfer();  impl->StepT( dt, prevIn );}//////////////////////////////////////////////////////////////////////////void TRIG_IMPL::StepT( SStepCalcParams &dt, bool prevIn ){  if( prevIn != IN )    OUT = 1;  else    OUT = 0;}